create extension if not exists pgcrypto;
create table project(id uuid primary key default gen_random_uuid(),name text not null,target_path text not null unique,status text not null default 'ACTIVE',version int not null default 1,content_hash text not null,created_at timestamptz not null default now(),created_by text not null default 'system',source_refs jsonb not null default '[]');
create table design_snapshot(id uuid primary key,project_id uuid references project(id),screen_id text not null,event_id text not null,design_version int not null,event_manifest_hash text,mockup_intent_hash text,architecture_profile_version int,artifact_versions jsonb not null default '{}',artifact_hashes jsonb not null default '{}',trace_coverage numeric(5,2) not null default 0,unresolved_items jsonb not null default '[]',evaluation_result jsonb not null default '{}',status text not null,content_hash text not null,approved_by text,approved_at timestamptz,integrity_hash text,version int not null default 1,created_at timestamptz not null default now(),created_by text not null default 'system',source_refs jsonb not null default '[]',unique(screen_id,event_id,design_version));
create table implementation_queue(id uuid primary key,snapshot_id uuid not null references design_snapshot(id),screen_id text not null,event_id text not null,status text not null,created_at timestamptz not null default now());
create table workloop_run(id uuid primary key default gen_random_uuid(),project_id uuid references project(id),thread_id uuid,loop_type text not null,screen_id text not null,event_id text not null,state text not null,design_snapshot_id uuid references design_snapshot(id),repository_revision text,iteration int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table run_phase(id uuid primary key default gen_random_uuid(),run_id uuid not null references workloop_run(id),internal_phase text not null,status text not null,evidence_refs jsonb not null default '[]',started_at timestamptz,ended_at timestamptz);
create table patch_bundle(id uuid primary key default gen_random_uuid(),run_id uuid references workloop_run(id),design_snapshot_id uuid references design_snapshot(id),design_version int,screen_id text not null,event_id text not null,changed_files jsonb not null default '[]',changed_symbols jsonb not null default '[]',unified_diff text not null default '',findings jsonb not null default '[]',evidence_refs jsonb not null default '[]',content_hash text not null default '',status text not null,created_at timestamptz not null default now());
create table trace_link(id uuid primary key default gen_random_uuid(),source_type text not null,source_id text not null,target_type text not null,target_id text not null,relation_type text not null,event_id text not null,version int not null,unique(source_type,source_id,target_type,target_id,event_id,version));
create index trace_link_event_idx on trace_link(event_id,version);
create table harness_version(id uuid primary key default gen_random_uuid(),loop_type text not null,version int not null,files jsonb not null,content_hash text not null,status text not null,created_at timestamptz not null default now(),created_by text not null,source_refs jsonb not null default '[]',unique(loop_type,version));
create table thread(id uuid primary key default gen_random_uuid(),name text not null,loop_type text not null,created_at timestamptz not null default now());
create table thread_message(id uuid primary key default gen_random_uuid(),thread_id uuid not null references thread(id),actor text not null,content text not null,created_at timestamptz not null default now());
create table evidence(id uuid primary key default gen_random_uuid(),run_id uuid references workloop_run(id),kind text not null,artifact_path text,content_hash text not null,summary jsonb not null default '{}',created_at timestamptz not null default now());
create table evaluation_finding(id uuid primary key default gen_random_uuid(),run_id uuid references workloop_run(id),category text not null,severity text not null,affected_artifact text not null,event_id text not null,evidence_id uuid references evidence(id),responsible_agent text,repair_instruction text,status text not null);
create table token_ledger(id uuid primary key default gen_random_uuid(),run_id uuid references workloop_run(id),agent text not null,input_tokens bigint not null,output_tokens bigint not null,duration_ms bigint not null,estimated_cost numeric(18,6),created_at timestamptz not null default now());
create table human_gate(id uuid primary key default gen_random_uuid(),run_id uuid references workloop_run(id),gate_type text not null,decision text,decided_by text,decided_at timestamptz,version int not null default 1);
create table audit_log(id bigserial primary key,actor text not null,action text not null,target_type text not null,target_id text,outcome text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table architecture_profile(id uuid primary key default gen_random_uuid(),name text not null unique,layers jsonb not null,version int not null default 1,content_hash text not null,status text not null default 'ACTIVE',created_at timestamptz not null default now(),created_by text not null);
